2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Navigation;
6	
7	use App\Enums\UserRole;
8	use App\Models\Team;
9	use App\Models\User;
10	use Illuminate\Support\Facades\View;
11	use PHPUnit\Framework\Attributes\Test;
12	use Tests\Feature\FeatureTestCase;
13	
14	/**
15	 * Capsule T3 — mobile primary navigation active state + scroll restoration contract.
16	 *
17	 * The rendered contract under test:
18	 *   - a current primary nav link is programmatically current (aria-current="page"),
19	 *     in the mobile variant as well as the desktop one, and exactly once per variant;
20	 *   - every primary nav link carries a stable, item-derived scroll-restoration key
21	 *     (data-scroll-key) that is identical for the desktop and mobile rendering of
22	 *     the same item;
23	 *   - the authenticated layout emits a scroll-restoration region marker
24	 *     (data-scroll-region) identifying the page being rendered;
25	 *   - existing filtering / badge / href / test-id behaviour is unchanged.
26	 */
27	class MobileNavScrollStateTest extends FeatureTestCase
28	{
29	    /**
30	     * @return array<int, array<string, mixed>>
31	     */
32	    private function navItems(): array
33	    {
34	        return [
35	            [
36	                'key' => 'tenant-dashboard',
37	                'label' => 'Dashboard',
38	                'route' => 'user.dashboard',
39	                'data_testid' => 'nav-dashboard',
40	                'active' => true,
41	            ],
42	            [
43	                'key' => 'tenant-events',
44	                'label' => 'Events',
45	                'route' => 'events.index',
46	                'data_testid' => 'nav-events',
47	                'active' => false,
48	                'badge' => 7,
49	            ],
50	            [
51	                'key' => 'tenant-billing',
52	                'label' => 'Billing',
53	                'route' => 'billing.index',
54	                'data_testid' => 'nav-billing',
55	                'active' => false,
56	            ],
57	        ];
58	    }
59	
60	    /**
61	     * @param  array<int, array<string, mixed>>  $items
62	     * @param  array<int, string>  $except
63	     */
64	    private function renderNav(string $variant, array $items, array $except = []): string
65	    {
66	        return View::make('components.topbar-navigation', [
67	            'items' => $items,
68	            'variant' => $variant,
69	            'except' => $except,
70	        ])->render();
71	    }
72	
73	    /**
74	     * Parse the rendered anchors into testid => attribute map so assertions read
75	     * the contract, not the markup ordering or class strings.
76	     *
77	     * @return array<string, array<string, string|null>>
78	     */
79	    private function links(string $html): array
80	    {
81	        preg_match_all('/<a\b[^>]*>/s', $html, $matches);
82	
83	        $links = [];
84	
85	        foreach ($matches[0] as $tag) {
86	            $attribute = static function (string $name) use ($tag): ?string {
87	                return preg_match('/\b' . preg_quote($name, '/') . '="([^"]*)"/', $tag, $found)
88	                    ? $found[1]
89	                    : null;
90	            };
91	
92	            $testid = $attribute('data-testid');
93	
94	            if ($testid === null) {
95	                continue;
96	            }
97	
98	            $links[$testid] = [
99	                'href' => $attribute('href'),
100	                'aria-current' => $attribute('aria-current'),
101	                'data-scroll-key' => $attribute('data-scroll-key'),
102	            ];
103	        }
104	
105	        return $links;
106	    }
107	
108	    #[Test]
109	    public function current_item_is_programmatically_current_in_both_variants(): void
110	    {
111	        $items = $this->navItems();
112	
113	        $desktop = $this->links($this->renderNav('desktop', $items));
114	        $mobile = $this->links($this->renderNav('mobile', $items));
115	
116	        $this->assertCount(3, $desktop);
117	        $this->assertCount(3, $mobile);
118	
119	        // AC1 — current-ness is exposed programmatically, in both variants.
120	        $this->assertSame('page', $desktop['nav-dashboard']['aria-current']);
121	        $this->assertSame('page', $mobile['nav-dashboard-mobile']['aria-current']);
122	
123	        // AC2 — exactly one current item per variant, and it is the same item.
124	        $currentDesktop = array_keys(array_filter(
125	            $desktop,
126	            static fn (array $link): bool => $link['aria-current'] === 'page',
127	        ));
128	        $currentMobile = array_keys(array_filter(
129	            $mobile,
130	            static fn (array $link): bool => $link['aria-current'] === 'page',
131	        ));
132	
133	        $this->assertSame(['nav-dashboard'], $currentDesktop);
134	        $this->assertSame(['nav-dashboard-mobile'], $currentMobile);
135	    }
136	
137	    #[Test]
138	    public function every_link_carries_a_stable_item_derived_scroll_key_shared_by_both_variants(): void
139	    {
140	        $items = $this->navItems();
141	
142	        $desktop = $this->links($this->renderNav('desktop', $items));
143	        $mobile = $this->links($this->renderNav('mobile', $items));
144	        $desktopAgain = $this->links($this->renderNav('desktop', $items));
145	
146	        $keys = [];
147	
148	        foreach ($items as $item) {
149	            $testid = $item['data_testid'];
150	            $desktopKey = $desktop[$testid]['data-scroll-key'] ?? null;
151	            $mobileKey = $mobile[$testid . '-mobile']['data-scroll-key'] ?? null;
152	
153	            $this->assertNotNull($desktopKey, "Desktop link {$testid} must expose a scroll-restoration key.");
154	            $this->assertNotSame('', $desktopKey, "Desktop link {$testid} scroll key must not be empty.");
155	
156	            // AC4 — same item ⇒ same key across variants.
157	            $this->assertSame($desktopKey, $mobileKey, "Scroll key for {$testid} must match across variants.");
158	
159	            // AC4 — stable across requests (re-render yields the same key).
160	            $this->assertSame($desktopKey, $desktopAgain[$testid]['data-scroll-key'] ?? null);
161	
162	            $keys[] = $desktopKey;
163	        }
164	
165	        // AC4 — derived from the navigation item, so distinct items get distinct keys.
166	        $this->assertSame($keys, array_values(array_unique($keys)));
167	    }
168	
169	    #[Test]
170	    public function existing_filtering_badge_href_and_testid_behaviour_is_preserved(): void
171	    {
172	        $items = $this->navItems();
173	
174	        $desktopHtml = $this->renderNav('desktop', $items);
175	        $mobileHtml = $this->renderNav('mobile', $items, ['tenant-billing']);
176	
177	        $desktop = $this->links($desktopHtml);
178	        $mobile = $this->links($mobileHtml);
179	
180	        // AC6 — hrefs unchanged.
181	        $this->assertSame(route('user.dashboard'), $desktop['nav-dashboard']['href']);
182	        $this->assertSame(route('events.index'), $desktop['nav-events']['href']);
183	
184	        // AC6 — badge still rendered.
185	        $this->assertStringContainsString('7', $desktopHtml);
186	        $this->assertMatchesRegularExpression('/<span[^>]*>\s*7\s*<\/span>/', $desktopHtml);
187	
188	        // AC6 — exclusion list still filters, AC3 — mobile keeps its distinct test ids.
189	        $this->assertArrayNotHasKey('nav-billing-mobile', $mobile);
190	        $this->assertSame(
191	            ['nav-dashboard-mobile', 'nav-events-mobile'],
192	            array_keys($mobile),
193	        );
194	        $this->assertSame(
195	            [],
196	            array_intersect(array_keys($desktop), array_keys($mobile)),
197	        );
198	    }
199	
200	    #[Test]
201	    public function authenticated_layout_emits_a_scroll_restoration_region_marker_for_the_page(): void
202	    {
203	        $user = $this->verifiedUser();
204	        $team = Team::factory()->create(['user_id' => $user->id, 'personal_team' => false]);
205	        $team->users()->syncWithoutDetaching([
206	            $user->getKey() => ['role' => UserRole::ADMIN->value],
207	        ]);
208	        $user->switchTeam($team);
209	
210	        $marker = function (User $user, string $routeName): string {
211	            $response = $this->actingAs($user)->get(route($routeName));
212	            $response->assertOk();
213	
214	            $matched = preg_match(
215	                '/data-scroll-region="([^"]+)"/',
216	                $response->getContent(),
217	                $found,
218	            );
219	
220	            $this->assertSame(
221	                1,
222	                $matched,
223	                "The authenticated layout must emit a scroll-restoration region marker on {$routeName}.",
224	            );
225	
226	            return $found[1];
227	        };
228	
229	        $personal = $marker($user, 'account.personal');
230	        $personalAgain = $marker($user, 'account.personal');
231	        $security = $marker($user, 'account.security');
232	
233	        // AC5 — stable for the same page so Back/Forward can restore its offset…
234	        $this->assertSame($personal, $personalAgain);
235	
236	        // …and it identifies the page being rendered, so a different page differs.
237	        $this->assertNotSame($personal, $security);
238	    }
239	}
