1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Providers;
6	
7	use App\Models\User;
8	use App\Navigation\NavigationResolver;
9	use Illuminate\Support\Facades\Auth;
10	use Illuminate\Support\ServiceProvider;
11	use Platform\UiNavigation\BreadcrumbBuilder;
12	use Platform\UiNavigation\Contracts\AdminResolverInterface;
13	
14	class PlatformNavigationServiceProvider extends ServiceProvider
15	{
16	    public function register(): void
17	    {
18	        $this->app->bind(AdminResolverInterface::class, fn() => new class implements AdminResolverInterface {
19	            public function isAdmin(\Illuminate\Contracts\Auth\Authenticatable $user): bool
20	            {
21	                return $user instanceof User && $user->isSystemAdmin();
22	            }
23	        });
24	
25	    }
26	
27	    public function boot(): void
28	    {
29	        // Share breadcrumbs with every view so in-container placements work
30	        // (Livewire full-page components render the content view before the
31	        // layout, so a layout-only composer fires too late).
32	        // once() ensures BreadcrumbBuilder->build() runs at most once per request.
33	        view()->composer('*', function ($view): void {
34	            $user = Auth::user();
35	
36	            if (!$user instanceof User) {
37	                return;
38	            }
39	
40	            if (array_key_exists('breadcrumbs', $view->getData())) {
41	                return;
42	            }
43	
44	            $breadcrumbs = once(fn () => $this->app->make(BreadcrumbBuilder::class)->build($user, $user->isSystemAdmin()));
45	            $view->with('breadcrumbs', $breadcrumbs);
46	        });
47	
48	        view()->composer(['layouts.authenticated'], function ($view): void {
49	            $user = Auth::user();
50	
51	            if (!$user instanceof User) {
52	                return;
53	            }
54	
55	            $resolver = $this->app->make(NavigationResolver::class);
56	            $allItems = $resolver->resolve($user);
57	
58	            $placedBuckets = ['user-menu', 'workspace-sidebar', 'account-sidebar'];
59	            $buckets = ['main' => [], 'user-menu' => [], 'workspace-sidebar' => [], 'account-sidebar' => []];
60	            foreach ($allItems as $item) {
61	                $placement = $item['placement'] ?? null;
62	                $bucket = \in_array($placement, $placedBuckets, true) ? $placement : 'main';
63	                $buckets[$bucket][] = $item;
64	            }
65	
66	            if (request()->routeIs('admin.*')) {
67	                $buckets['main'] = array_values(array_filter(
68	                    $buckets['main'],
69	                    static fn (array $item): bool => str_starts_with((string) ($item['key'] ?? ''), 'super-admin-'),
70	                ));
71	
72	                $buckets['user-menu'] = array_values(array_filter(
73	                    $buckets['user-menu'],
74	                    static fn (array $item): bool => ($item['key'] ?? null) !== 'user-workspace',
75	                ));
76	            }
77	
78	            $breadcrumbs = $this->app->make(BreadcrumbBuilder::class)->build($user, $user->isSystemAdmin());
79	
80	            $view->with([
81	                'navigationMenu' => $buckets['main'],
82	                'userMenu' => $buckets['user-menu'],
83	                'workspaceSidebarMenu' => $buckets['workspace-sidebar'],
84	                'accountSidebarMenu' => $buckets['account-sidebar'],
85	                'breadcrumbs' => $breadcrumbs,
86	            ]);
87	        });
88	    }
89	
90	}
