1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Navigation;
6	
7	use App\Models\User;
8	use Platform\UiNavigation\ActiveStateResolver;
9	use Platform\UiNavigation\NavigationBuilder;
10	
11	/**
12	 * Single entry-point for resolving navigation items for a user.
13	 *
14	 * Owns the cache key + active-state pipeline so the view composer and
15	 * render-context-independent components (e.g. WorkspaceSidebar) both go
16	 * through the same code path and hit the same cache.
17	 */
18	class NavigationResolver
19	{
20	    public function __construct(
21	        private readonly NavigationBuilder $builder,
22	        private readonly ActiveStateResolver $activeStates,
23	    ) {}
24	
25	    /**
26	     * Resolve the full, capability-filtered, active-state-decorated menu.
27	     *
28	     * @return array<int, array<string, mixed>>
29	     */
30	    public function resolve(User $user): array
31	    {
32	        $menu = $this->cached($user);
33	
34	        return $this->activeStates->updateActiveStates($menu);
35	    }
36	
37	    /**
38	     * Resolve items for a specific placement (or null for main nav — items
39	     * without any placement set).
40	     *
41	     * @return array<int, array<string, mixed>>
42	     */
43	    public function byPlacement(User $user, ?string $placement): array
44	    {
45	        return array_values(array_filter(
46	            $this->resolve($user),
47	            static fn (array $item): bool => ($item['placement'] ?? null) === $placement,
48	        ));
49	    }
50	
51	    /**
52	     * @return array<int, array<string, mixed>>
53	     */
54	    private function cached(User $user): array
55	    {
56	        $cacheDuration = (int) config('platform-navigation.cache_duration', 3600);
57	
58	        if ($cacheDuration <= 0) {
59	            return $this->builder->build($user, $user->current_team_id);
60	        }
61	
